<?php require '../config/database.php';require '../config/auth.php';require_role('student');$msg='';$qs=$pdo->query('SELECT * FROM questions WHERE active=1 ORDER BY id LIMIT 20')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$score=0;foreach($qs as $q)if(($_POST['a'][$q['id']]??'')===$q['correct_answer'])$score++;$msg="Test submitted. Score: $score / ".count($qs);}$page_title='Take Test';require '../includes/header.php';?><h1>Take Test</h1><p class="muted">Online practice test.</p><?php if($msg):?><div class="alert success"><?=$msg?></div><?php endif;?><div class="card"><form method="post"><?php foreach($qs as $i=>$q):?><div style="margin-bottom:22px"><b><?=$i+1?>. <?=htmlspecialchars($q['question'])?></b><?php foreach(['A','B','C','D'] as $o):$f='option_'.strtolower($o);?><label style="display:block;margin-top:8px"><input type="radio" name="a[<?=$q['id']?>]" value="<?=$o?>" required> <?=htmlspecialchars($q[$f])?></label><?php endforeach;?></div><?php endforeach;?><button class="btn">Submit Test</button></form></div><?php require '../includes/footer.php';?>
